package org.jsoup.nodes;

import org.junit.Test;
import static org.junit.Assert.*;

public class TextNodeTest {

    @Test
    public void getNodeNameIsEmptyTextNode() {
        TextNode textNode = new TextNode("");
        assertEquals("", textNode.nodeName());
    }

    @Test
    public void getNodeNameIsNotEmptyNonEmptyTextNode() {
        String text = "not empty";
        TextNode textNode = new TextNode(text);
        assertEquals(text, textNode.nodeName());
    }

    @Test
    public void getTextIsEmptyTextNode() {
        TextNode textNode = new TextNode("");
        assertEquals("", textNode.text());
    }

    @Test
    public void getTextReturnsStringifiedTextNonEmptyTextNode() {
        String text = "not empty";
        TextNode textNode = new TextNode(text);
        assertEquals(text, textNode.text());
    }

    @Test
    public void getTextModifiedWhenReplacingWithNewText() {
        TextNode textNode = new TextNode("initial");
        TextNode newText = new TextNode("new");
        textNode.text(newText.text());
        assertEquals(newText.text(), textNode.text());
    }

    @Test
    public void getWholeTextIsEmptyTextNode() {
        TextNode textNode = new TextNode("");
        assertTrue(textNode.getWholeText().isEmpty());
    }

    @Test
    public void getWholeTextReturnsStringifiedTextNonEmptyTextNode() {
        String text = "not empty";
        TextNode textNode = new TextNode(text);
        assertEquals(text, textNode.getWholeText());
    }

    @Test
    public void isBlankIsEmptyTextNode() {
        TextNode textNode = new TextNode("");
        assertTrue(textNode.isBlank());
    }

    @Test
    public void isBlankReturnsFalseNonEmptyTextNode() {
        String text = "not empty";
        TextNode textNode = new TextNode(text);
        assertFalse(textNode.isBlank());
    }

    @Test
    public void splitTextOffsetAtStartOfText() {
        TextNode textNode = new TextNode("initial");
        TextNode result = textNode.splitText(0);
        assertNotNull(result);
        assertTrue(result.text().isEmpty());
    }

    @Test
    public void splitTextOffsetInTheMiddleOfText() {
        TextNode textNode = new TextNode("initial");
        String text = "initial";
        int offset = 6;
        TextNode result = textNode.splitText(offset);
        assertNotNull(result);
        assertEquals(text.substring(0, offset), result.text());
    }

    @Test
    public void splitTextOffsetAtEndOfText() {
        TextNode textNode = new TextNode("initial");
        String text = "initial";
        int offset = text.length();
        TextNode result = textNode.splitText(offset);
        assertNotNull(result);
        assertTrue(result.text().isEmpty());
    }

    @Test
    public void outerHtmlHeadReturnsEmptyStringWhenNoContent() {
        Appendable accum = new StringBuilder();
        Document.OutputSettings out = null;
        int depth = 0;
        TextNode textNode = new TextNode("");
        String html = textNode.outerHtmlHead(accum, depth, out);
        assertTrue(html.isEmpty());
    }

    @Test
    public void outerHtmlTailReturnsEmptyStringWhenNoContent() {
        Appendable accum = new StringBuilder();
        Document.OutputSettings out = null;
        int depth = 0;
        TextNode textNode = new TextNode("");
        String html = textNode.outerHtmlTail(accum, depth, out);
        assertTrue(html.isEmpty());
    }

    @Test
    public void toStringReturnsStringifiedText() {
        String text = "not empty";
        TextNode textNode = new TextNode(text);
        assertEquals("<text>" + text + "</text>", textNode.toString());
    }

    @Test
    public void cloneCreatesNewTextNodeWithSameContent() {
        String text = "initial";
        TextNode original = new TextNode(text);
        TextNode cloned = original.clone();
        assertNotNull(cloned);
        assertEquals(original.text(), cloned.text());
    }

    @Test
    public void createFromEncodedReturnsValidTextNode() throws IOException {
        String encodedText = "<text>encoded</text>";
        TextNode textNode = TextNode.createFromEncoded(encodedText);
        assertNotNull(textNode);
        assertTrue(textNode.text().equals("encoded"));
    }
}
